const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const year = 2023;
    const startDate = ee.Date.fromYMD(year, 1, 1);
    const endDate = ee.Date.fromYMD(year, 12, 31);
    const targetAreaHa = 160000; // Target in hectares

    // Define Quebec geometry from FAO/GAUL dataset
    const countries = ee.FeatureCollection('FAO/GAUL/2015/level1');
    const quebec = countries.filter(ee.Filter.eq('ADM1_NAME', 'Quebec'));

    if (quebec.size().getInfo() === 0) {
      console.log("Error: Could not find Quebec geometry.");
      console.log("C3"); // Calculation failure, as geometry is crucial.
      return;
    }

    // 2. Data Acquisition & Check
    // Using MODIS MCD64A1 V6.1 Burned Area product
    const burnedAreaCollection = ee.ImageCollection('MODIS/061/MCD64A1')
      .filterDate(startDate, endDate)
      .filterBounds(quebec);

    const collectionSize = burnedAreaCollection.size().getInfo();
    if (collectionSize === 0) {
      console.log(`No MODIS MCD64A1 images found for Quebec in ${year}.`);
      console.log("C1");
      return;
    }
    console.log(`Images found for ${year}: ${collectionSize}`);

    // 3. Processing
    // Calculate burned area for each image and sum them up
    // The 'BurnDate' band contains the day of the year the burn occurred (1-366).
    // Pixels with 'BurnDate' > 0 are burned.
    const totalBurnedAreaSqM = burnedAreaCollection.map(function(image) {
      const burnedPixels = image.select('BurnDate').gt(0); // Create a binary mask: 1 for burned, 0 for not burned
      // Calculate the area of burned pixels within the Quebec geometry
      const areaImage = burnedPixels.multiply(ee.Image.pixelArea()); // Area in square meters per pixel
      return areaImage.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: quebec,
        scale: 500, // MODIS resolution is 500m
        maxPixels: 1e9
      }).get('BurnDate'); // Get the sum of square meters for burned areas
    }).sum(); // Sum the results from all monthly images

    const totalBurnedAreaSqMValue = await new Promise((resolve, reject) => {
      totalBurnedAreaSqM.evaluate((val, err) => {
        if (err) reject(err);
        else resolve(val);
      });
    });

    if (totalBurnedAreaSqMValue === null || isNaN(totalBurnedAreaSqMValue)) {
      console.log("Calculation of total burned area failed (None/NaN).");
      console.log("C3");
      return;
    }

    // Convert total area from square meters to hectares
    const totalBurnedAreaHa = totalBurnedAreaSqMValue / 10000; // 1 hectare = 10,000 sq meters

    // 4. Validation & Final Answer
    console.log(`Total burned area in Quebec in ${year}: ${totalBurnedAreaHa.toFixed(2)} hectares.`);

    if (totalBurnedAreaHa === 0) {
      // It's possible to have 0 burned pixels and that's a valid result, not an error.
      const firstImage = burnedAreaCollection.first();
      const pixelCountReducer = ee.Reducer.count();
      const initialPixelCount = await new Promise((resolve, reject) => {
        firstImage.select('BurnDate').reduceRegion({
          reducer: pixelCountReducer,
          geometry: quebec,
          scale: 500,
          maxPixels: 1e9
        }).get('BurnDate').evaluate((val, err) => {
          if (err) reject(err);
          else resolve(val);
        });
      });
      if (initialPixelCount === 0) {
        console.log("No valid pixels found within Quebec for the first image of the collection.");
        console.log("C2");
        return;
      }
    }

    if (totalBurnedAreaHa > targetAreaHa) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (e) {
    console.error("An error occurred during analysis:", e);
    console.log("D"); // General error/failure
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
